// Package grpc contains the inbound ConnectRPC adapter for the irrigation-service.
// It translates proto request/response types into domain types and delegates
// all business logic to the inbound.IrrigationService port. Proto<->domain
// mapping is inlined here; there is no separate mappers package.
// NOTE: proto types are generated by buf generate.
package grpc

import (
	"time"

	"connectrpc.com/connect"
	"google.golang.org/protobuf/types/known/timestamppb"

	"context"

	"p9e.in/samavaya/packages/errors"
	"p9e.in/samavaya/packages/p9context"
	"p9e.in/samavaya/packages/p9log"

	// Generated by buf generate
	pb "p9e.in/samavaya/agriculture/irrigation-service/api/v1"
	"p9e.in/samavaya/agriculture/irrigation-service/api/v1/irrigationv1connect"
	"p9e.in/samavaya/agriculture/irrigation-service/internal/domain"
	"p9e.in/samavaya/agriculture/irrigation-service/internal/ports/inbound"
)

// IrrigationHandler is the ConnectRPC inbound adapter.
type IrrigationHandler struct {
	irrigationv1connect.UnimplementedIrrigationServiceHandler
	svc inbound.IrrigationService
	log *p9log.Helper
}

// NewIrrigationHandler creates a new ConnectRPC irrigation handler.
func NewIrrigationHandler(svc inbound.IrrigationService, log p9log.Logger) *IrrigationHandler {
	return &IrrigationHandler{
		svc: svc,
		log: p9log.NewHelper(p9log.With(log, "component", "IrrigationHandler")),
	}
}

// ---------------------------------------------------------------------------
// Schedule management
// ---------------------------------------------------------------------------

// CreateSchedule handles schedule creation requests.
func (h *IrrigationHandler) CreateSchedule(ctx context.Context, req *connect.Request[pb.CreateScheduleRequest]) (*connect.Response[pb.CreateScheduleResponse], error) {
	h.log.Infow("msg", "CreateSchedule request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetSchedule() == nil || req.Msg.GetSchedule().GetName() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "schedule with name is required")
	}
	entity := scheduleFromProto(req.Msg.GetSchedule())
	created, err := h.svc.CreateSchedule(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.CreateScheduleResponse{Schedule: scheduleToProto(created)}), nil
}

// GetSchedule handles get schedule requests.
func (h *IrrigationHandler) GetSchedule(ctx context.Context, req *connect.Request[pb.GetScheduleRequest]) (*connect.Response[pb.GetScheduleResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	entity, err := h.svc.GetSchedule(ctx, req.Msg.GetId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.GetScheduleResponse{Schedule: scheduleToProto(entity)}), nil
}

// ListSchedules handles list schedules requests.
func (h *IrrigationHandler) ListSchedules(ctx context.Context, req *connect.Request[pb.ListSchedulesRequest]) (*connect.Response[pb.ListSchedulesResponse], error) {
	pageSize := req.Msg.GetPageSize()
	offset := req.Msg.GetPageOffset()

	var schedules []domain.IrrigationSchedule
	var total int32
	var err error

	switch {
	case req.Msg.GetZoneId() != "":
		schedules, total, err = h.svc.ListSchedulesByZone(ctx, req.Msg.GetZoneId(), pageSize, offset)
	default:
		schedules, total, err = h.svc.ListSchedulesByField(ctx, req.Msg.GetFieldId(), pageSize, offset)
	}

	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	out := make([]*pb.IrrigationSchedule, len(schedules))
	for i := range schedules {
		out[i] = scheduleToProto(&schedules[i])
	}
	return connect.NewResponse(&pb.ListSchedulesResponse{
		Schedules:  out,
		TotalCount: total,
	}), nil
}

// UpdateSchedule handles schedule update requests.
func (h *IrrigationHandler) UpdateSchedule(ctx context.Context, req *connect.Request[pb.UpdateScheduleRequest]) (*connect.Response[pb.UpdateScheduleResponse], error) {
	if req.Msg.GetSchedule() == nil || req.Msg.GetSchedule().GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "schedule with id is required")
	}
	entity := scheduleFromProto(req.Msg.GetSchedule())
	entity.ID = req.Msg.GetSchedule().GetId()
	updated, err := h.svc.UpdateSchedule(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.UpdateScheduleResponse{Schedule: scheduleToProto(updated)}), nil
}

// DeleteSchedule handles schedule deletion requests.
func (h *IrrigationHandler) DeleteSchedule(ctx context.Context, req *connect.Request[pb.DeleteScheduleRequest]) (*connect.Response[pb.DeleteScheduleResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	if err := h.svc.CancelSchedule(ctx, req.Msg.GetId()); err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.DeleteScheduleResponse{Success: true}), nil
}

